[metadata] {"type": "create", "filePath": "/workspace/repo/crates/test-programs/src/bin/p1_file_truncation_readonly.rs", "content": "#![expect(unsafe_op_in_unsafe_fn, reason = "old code, not worth updating yet")]

use std::process;
use test_programs::preview1::open_scratch_directory;

/// The contents that `test.txt` is expected to hold on the host, both before
/// and after this program runs. Truncation must be rejected, so the file must
/// remain byte-for-byte identical.
const CONTENTS: &[u8] = b"truncation test file\n";

unsafe fn test_readonly_truncation(dir_fd: wasip1::Fd) {
    const FILENAME: &str = "test.txt";

    // Attempt to open the file with the truncate flag. Because the directory
    // was preopened with read-only file permissions, the runtime must reject
    // this operation rather than truncating the file. The program must not
    // trap: we assert that an error is returned and continue.
    let res = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        wasip1::OFLAGS_TRUNC,
        wasip1::RIGHTS_FD_READ,
        0,
        0,
    );
    assert!(
        res.is_err(),
        "truncating a file in a read-only directory must be rejected"
    );

    // Re-open the file read-only and confirm from within the guest that its
    // contents are unchanged: the failed truncation must not have modified it.
    let file_fd = wasip1::path_open(dir_fd, 0, FILENAME, 0, wasip1::RIGHTS_FD_READ, 0, 0)
        .expect("opening the file for reading");

    let buffer = &mut [0u8; 128];
    let nread = wasip1::fd_read(
        file_fd,
        &[wasip1::Iovec {
            buf: buffer.as_mut_ptr(),
            buf_len: buffer.len(),
        }],
    )
    .expect("reading file content");

    assert_eq!(
        &buffer[..nread],
        CONTENTS,
        "file contents must be unchanged after a rejected truncation"
    );

    wasip1::fd_close(file_fd).expect("closing the file");
}

fn main() {
    // Open the preopened directory that was mounted read-only by the host.
    let dir_fd = match open_scratch_directory("readonly") {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            process::exit(1)
        }
    };

    unsafe {
        test_readonly_truncation(dir_fd);
    }
}
