use test_programs::wasi::filesystem::types::{DescriptorFlags, OpenFlags, PathFlags};

/// The contents that `test.txt` is expected to hold on the host, both before
/// and after this program runs. Truncation must be rejected, so the file must
/// remain byte-for-byte identical.
const CONTENTS: &[u8] = b"truncation test file\n";

fn main() {
    // Find the directory that the host preopened with read-only file
    // permissions.
    let preopens = wasi::filesystem::preopens::get_directories();
    let (dir, _name) = preopens
        .iter()
        .find(|(_, name)| name == "readonly")
        .expect("must have a preopened `readonly` directory");

    let filename = "test.txt";

    // Attempt to truncate the file by opening it with the truncate flag.
    // Because the directory was preopened with read-only file permissions, the
    // runtime must reject this operation rather than truncating the file. The
    // program must not trap: we assert an error is returned and continue.
    let res = dir.open_at(
        PathFlags::empty(),
        filename,
        OpenFlags::TRUNCATE,
        DescriptorFlags::READ,
    );
    assert!(
        res.is_err(),
        "truncating a file in a read-only directory must be rejected"
    );

    // Re-open the file read-only and confirm from within the guest that its
    // contents are unchanged: the failed truncation must not have modified it.
    let file = dir
        .open_at(
            PathFlags::empty(),
            filename,
            OpenFlags::empty(),
            DescriptorFlags::READ,
        )
        .expect("opening the file for reading");
    let stream = file.read_via_stream(0).unwrap();
    let contents = stream
        .blocking_read(CONTENTS.len() as u64)
        .expect("reading file content");
    assert_eq!(
        contents, CONTENTS,
        "file contents must be unchanged after a rejected truncation"
    );
}
